import boto3

def get_bedrock_client(region_name="us-east-1"):
    return boto3.client("bedrock-runtime", region_name=region_name)

def get_bedrock_embedding(texts, client, model_id="amazon.titan-embed-text-v2:0"):
    if isinstance(texts, str):
        texts = [texts]

    # Amazon Bedrock Titan Embeddings accept a single text or a batch of texts
    if len(texts) == 1:
        body = {"inputText": texts[0]}
        response = client.invoke_model(modelId=model_id, body=json.dumps(body), contentType="application/json", accept="application/json")
        stream = response["body"]
        try:
            return json.loads(stream.read())["embedding"]
        finally:
            stream.close()
    else:
        # For batch, Bedrock Titan Embeddings does not directly support a batch input for invoke_model
        # So we iterate and get embeddings one by one. This might be slow for large batches.
        # A more efficient approach for large batches would involve a different API or custom handling.
        embeddings = []
        for text in texts:
            body = {"inputText": text}
            response = client.invoke_model(modelId=model_id, body=json.dumps(body), contentType="application/json", accept="application/json")
            stream = response["body"]
            try:
                embeddings.append(json.loads(stream.read())["embedding"])
            finally:
                stream.close()
        return embeddings

