import json

import boto3

from embeddings_client import get_bedrock_client, invoke_bedrock_text_embedding_model

def embed_for_search(payload, config=None):
    config = config or {}
    client = get_bedrock_client(region_name=config.get("region", "us-east-1"))

    query_embedding = invoke_bedrock_text_embedding_model(client, payload["query"], model_id="amazon.titan-embed-text-v2:0")

    document_embeddings = []
    for doc_text in payload["documents"]:
        document_embeddings.append(invoke_bedrock_text_embedding_model(client, doc_text, model_id="amazon.titan-embed-text-v2:0"))

    return {"query_embedding": query_embedding, "document_embeddings": document_embeddings}

import os

from azure.ai.contentsafety import ContentSafetyClient
from azure.core.credentials import AzureKeyCredential
from azure.ai.contentsafety.models import AnalyzeTextOptions, TextCategory

def corpus_safety(text_to_check, config=None):
    config = config or {}
    endpoint = config.get("azure_content_safety_endpoint")
    key = config.get("azure_content_safety_key")

    if not endpoint or not key:
        raise ValueError("Azure Content Safety endpoint and key must be provided in config.")

    client = ContentSafetyClient(endpoint=endpoint, credential=AzureKeyCredential(key))

    request = AnalyzeTextOptions(
        text=text_to_check,
        categories=[TextCategory.HATE, TextCategory.SELF_HARM, TextCategory.SEXUAL, TextCategory.VIOLENCE]
    )

    response = client.analyze_text(request)

    safety_scores = {
        category.category.value: {"severity": category.severity} 
        for category in response.categories_analysis
    }

    return {"safety_scores": safety_scores}

from google.cloud import translate

def multilingual_query_translate(query_text, target_language, config=None):
    config = config or {}
    project_id = config.get("project_id")

    if not project_id:
        raise ValueError("Google Cloud project_id must be provided in config.")

    client = translate.TranslationServiceClient()
    parent = f"projects/{project_id}/locations/global"

    response = client.translate_text(
        request={
            "parent": parent,
            "contents": [query_text],
            "target_language_code": target_language,
        }
    )

    translations = []
    for translation in response.translations:
        translations.append(translation.translated_text)

    return {"translated_queries": translations}
